    @staticmethod
    def _process_response(data):
        # Create a mapping from nodeId to nodeName
        node_map = {}
        for node in data['knowledgeList']:
            if node.get('nodeName', '') != '':
                node_map[node['nodeId']] = (node['nodeName'], node['nodeUid'])

        processed_list = []
        for relation in data['knowledgeRelationDtoList']:
            if relation['fromNodeId'] not in node_map or relation['toNodeId'] not in node_map:
                continue
            processed_entry = {
                "fromNodeName": node_map.get(relation['fromNodeId'], "")[0],
                "fromNodeUid": node_map.get(relation['fromNodeId'], "")[1],
                "relationName": relation['relationName'],
                "toNodeName": node_map.get(relation['toNodeId'], "")[0],
                "toNodeUid": node_map.get(relation['toNodeId'], "")[1],
                'method': 'GDB'
            }
            processed_list.append(processed_entry)
        return processed_list
